package com.hospital.smartqueue.hospital.application;
import com.hospital.smartqueue.common.domain.*; import com.hospital.smartqueue.common.infrastructure.AuditService; import com.hospital.smartqueue.hospital.domain.*; import com.hospital.smartqueue.hospital.infrastructure.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class HospitalService { private final HospitalRepository hospitals; private final BranchRepository branches; private final AuditService audit; public HospitalService(HospitalRepository h,BranchRepository b,AuditService a){hospitals=h;branches=b;audit=a;} private String n(String s){if(s==null||s.trim().isEmpty())throw new DomainException("Name is required");return s.trim();}
 @Transactional public Hospital createHospital(String name){Hospital h=hospitals.save(new Hospital(UUID.randomUUID(),n(name)));audit.record("HOSPITAL_CREATED","HOSPITAL",h.getId(),h.getId(),null);return h;} public List<Hospital> listHospitals(){return hospitals.findAll();}
 @Transactional public Branch createBranch(UUID hospitalId,String name){if(!hospitals.existsById(hospitalId))throw new NotFoundException("Hospital not found");Branch b=branches.save(new Branch(UUID.randomUUID(),hospitalId,n(name)));audit.record("BRANCH_CREATED","BRANCH",b.getId(),hospitalId,null);return b;} public List<Branch> listBranches(UUID hospitalId){if(!hospitals.existsById(hospitalId))throw new NotFoundException("Hospital not found");return branches.findByHospitalId(hospitalId);}}
